def is_sqrt(expr):
    return expr.is_Pow and expr.exp is S.Half
# p = c1*sqrt(q1) + ... + cn*sqrt(qn) -> a = [(c1, q1), .., (cn, qn)]
a = []
unevaluated = False
for y in p.args:
    if not y.is_Mul:
        if is_sqrt(y):
            a.append((S.One, y**2))
        elif y.is_Atom:
            a.append((y, S.One))
        elif y.is_Pow and y.exp.is_integer:
            a.append((y, S.One))
        elif (y**2).is_Rational and y.is_extended_real:
            # y is an unevaluated algebraic expression like
            # exp(3*I*pi, evaluate=False) or Pow(8, Rational(1, 3),
            # evaluate=False); write it as +-sqrt(y**2)
            if y.is_nonnegative:
                a.append((S.One, y**2))
            elif y.is_negative:
                a.append((S.NegativeOne, y**2))
            else:
                raise NotImplementedError
            unevaluated = True
        else:
            raise NotImplementedError
    else:
        T, F = sift(y.args, is_sqrt, binary=True)
        a.append((Mul(*F), Mul(*T)**2))
a.sort(key=lambda z: z[1])
if a[-1][1] is S.One:
    # there are no surds
    if unevaluated:
        # some terms were rewritten, e.g. exp(3*I*pi, evaluate=False)
        # was replaced by -sqrt(1); rebuild the expression from them
        return Add(*[c*q**S.Half for c, q in a])
